// Parity with the Python client on what each pattern yields.
//
// `pattern-vectors.json` is generated by `gen-pattern-vectors.py` from the
// Python client's patterns and committed; here the TS client builds the same
// patterns, case by case under the same names, and must yield the same values.
// A case that draws seeds the random context first: both clients draw from the
// same core generator, so the draws are asserted exactly too.
//
// Exact everywhere but the transcendental operators (`midicps`), which go
// through libm and are held to one f32 ulp -- the posture `docs/decisions.md`
// records under "Native<->wasm render parity is a tight tolerance".

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";

import { loadCore } from "../src/base/core.ts";
import { seed } from "../src/base/rand.ts";
import * as b from "../src/base/builtins.ts";
import {
    INF,
    pconst,
    pfunc,
    pgeom,
    pn,
    pnarop,
    prand,
    pseq,
    pser,
    pseries,
    pwhite,
} from "../src/seq/index.ts";
import type { Pattern } from "../src/seq/index.ts";

await loadCore();

const TAKE = 8;

/** name -> the pattern; the names are `gen-pattern-vectors.py`'s. */
const CASES: Record<string, () => Pattern<unknown>> = {
    pseq: () => pseq([1, 2, 3], 2),
    pseq_nested: () => pseq<number>([1, pseq([8, 9]), 2]),
    pseq_endless: () => pseq([1, 2], INF),
    pser: () => pser([1, 2, 3], 5),
    pconst: () => pconst(7, 3),
    pseries: () => pseries(0, 2.5, 4),
    pgeom: () => pgeom(1, 3, 5),
    pn: () => pn(pseq([1, 2]), 3),
    pfunc: () => pfunc(() => 4, 3),
    pwhite: () => pwhite(-1, 1, 6),
    prand: () => prand([10, 20, 30], 6),
    add: () => pseq([74, 60, 46]).add(2),
    mul_shorter: () => pseq([1, 2, 3]).mul(pseq([10, 20])),
    ops_chain: () => pseries(0, 1, 6).mul(7).mod(12).max(3),
    midicps: () => pseq([57, 69, 81]).midicps(),
    linlin: () => pnarop("linlin", pseq([0, 0.25, 1, 2]), 0, 1, 10, 20),
    clip: () => pnarop("clip", pseq([-2, 0.5, 3]), 0, 1),
    random_ops: () => pwhite(0, 1, 6).mul(100).floor(),
    linlin_method: () => pseq([0, 0.5, 1, 2]).linlin(0, 1, 200, 800, "max"),
    lincurve_method: () => pseq([0, 0.25, 0.5, 1]).lincurve(0, 1, 0, 10, -4),
    fold_method: () => pseq([-0.5, 1.5, 2.25]).fold(0, 1),
    blend: () => pseq([0, 10, 20]).blend(pseq([100, 50, 0]), 0.25),
    angles: () => pseq([0, 90, 270]).degrad().raddeg(),
    moddif: () => pseq([0.1, 0.9, 0.5]).moddif(0.2),
    bilin: () => pseq([0, 0.25, 0.5, 0.75, 1]).bilin(0.5, 0, 1, 10, 0, 100),
    bit_ops: () => pseq([0, 5]).bitnot().idiv(2).bitand(7),
    not: () => pseq([-1, 0, 1]).not(),
    draws: () => pseq([10, 10, 10]).rand().add(pseq([1, 1, 1]).exprand(2)),
    builtin_midicps: () => b.midicps(pseq([60, 72])),
    builtin_reflected: () => b.sub(100, pseq([1, 2, 3])),
    builtin_by_name: () => b.degkey(pseq([0, 3, 7, -1]), [0, 2, 4, 5, 7, 9, 11]),
};

const TRANSCENDENTAL = new Set(["midicps", "builtin_midicps", "lincurve_method"]);

const vectors: Record<string, { seed: number | null; values: number[] }> = JSON.parse(
    await readFile(new URL("./pattern-vectors.json", import.meta.url), "utf8"),
);

const take = (p: Pattern<unknown>): number[] => {
    const out: number[] = [];
    for (const x of p) {
        if (out.length === TAKE) break;
        out.push(Number(x));
    }
    return out;
};

const ulp = (x: number): number => {
    const f = new Float32Array([Math.abs(x)]);
    const bits = new Uint32Array(f.buffer);
    bits[0] = bits[0]! + 1;
    return f[0]! - Math.fround(Math.abs(x));
};

test("every case is on both sides", () => {
    assert.deepEqual(Object.keys(CASES).sort(), Object.keys(vectors).sort());
});

for (const [name, expected] of Object.entries(vectors)) {
    test(`${name} yields what the Python client's yields`, () => {
        if (expected.seed !== null) seed(expected.seed);
        const got = take(CASES[name]!());
        assert.equal(got.length, expected.values.length);
        got.forEach((v, i) => {
            const want = expected.values[i]!;
            if (TRANSCENDENTAL.has(name)) assert.ok(Math.abs(v - want) <= ulp(want), `${v} vs ${want}`);
            else assert.equal(v, want);
        });
    });
}
